const variants: KeywordPageConfig["svgVariant"][] = ["serp", "analytics", "ai", "local", "audit", "growth"];

function makeSeo(slug: string, keyword: string, badge: string, title: string, metaDesc: string, h1: string, intro: string, scope: string, featuresTitle: string, featuresSubtitle: string, faqTitle: string, ctaTitle: string, ctaDesc: string, ctaButton: string, area = "Worldwide"): KeywordPageConfig {
  return {
    slug, keyword, badge, title, metaDesc, h1, intro,
    svgVariant: variants[pick(slug, variants.length)],
    imageUrl: img(pick(slug, IMAGES.length)),
    featuresTitle, featuresSubtitle,
    features: seoFeatures(keyword, scope),
    stats: statSets[pick(slug, statSets.length)],
    faqTitle, faqs: seoFaqs(keyword),
    ctaTitle, ctaDesc, ctaButton, areaServed: area,
  };
}

function makeWeb(slug: string, keyword: string, badge: string, title: string, metaDesc: string, h1: string, intro: string, scope: string, featuresTitle: string, featuresSubtitle: string, faqTitle: string, ctaTitle: string, ctaDesc: string, ctaButton: string, area = "Worldwide"): KeywordPageConfig {
  return {
    slug, keyword, badge, title, metaDesc, h1, intro,
    svgVariant: variants[pick(slug, variants.length)],
    imageUrl: img(pick(slug, IMAGES.length)),
    featuresTitle, featuresSubtitle,
    features: webFeatures(keyword, scope),
    stats: statSets[pick(slug, statSets.length)],
    faqTitle, faqs: webFaqs(keyword),
    ctaTitle, ctaDesc, ctaButton, areaServed: area,
  };
}

function makeSocial(slug: string, keyword: string, badge: string, title: string, metaDesc: string, h1: string, intro: string, scope: string, featuresTitle: string, featuresSubtitle: string, faqTitle: string, ctaTitle: string, ctaDesc: string, ctaButton: string, area = "Worldwide"): KeywordPageConfig {
  return {
    slug, keyword, badge, title, metaDesc, h1, intro,
    svgVariant: variants[pick(slug, variants.length)],
    imageUrl: img(pick(slug, IMAGES.length)),
    featuresTitle, featuresSubtitle,
    features: socialFeatures(keyword, scope),
    stats: statSets[pick(slug, statSets.length)],
    faqTitle, faqs: socialFaqs(keyword),
    ctaTitle, ctaDesc, ctaButton, areaServed: area,
  };
}

